import {
  ISSUE_PRIORITIES,
  type IssueFilter,
  type IssuePriority,
} from "@/types/issue";

export const UNASSIGNED_TOKEN = "none";

export interface ReadableParams {
  get(name: string): string | null;
}

type PageSearchParams = Readonly<
  Record<string, string | string[] | undefined>
>;

function splitList(raw: string | null): readonly string[] {
  if (raw === null || raw.length === 0) return [];
  return raw
    .split(",")
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
}

export function parseIssueFilterParams(
  params: ReadableParams | PageSearchParams,
): IssueFilter {
  const get = (name: string): string | null => {
    if (typeof params.get === "function") return params.get(name);
    const value = (params as PageSearchParams)[name];
    return Array.isArray(value) ? value.join(",") : value ?? null;
  };
  const statuses = expandIssueStatuses(splitList(get("status")));
  const priorities = splitList(get("priority")).filter(
    (value): value is IssuePriority =>
      ISSUE_PRIORITIES.includes(value as IssuePriority),
  );
  const labelIds = splitList(get("label")) as readonly LabelId[];
