/bin/zsh -lc "pnpm exec tsx --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { mkdtempSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { runMigrations } from './src/server/db/migrate.ts';
import { createTenant, issueInput } from './tests/server/_support/fixtures.ts';
import * as repo from './src/server/repositories/issue-repository.ts';
import * as labels from './src/server/repositories/label-repository.ts';
import { listIssues } from './src/server/services/issue-service.ts';
import { issueFilterSchema } from './src/schemas/issue.ts';
import { exportIssuesSchema } from './src/schemas/export.ts';
import { parseIssueFilterParams, issueFilterToParams } from './src/hooks/issue-filter-params.ts';
import { toggleStatus } from './src/components/domain/issue/issue-filter-bar.tsx';

const dir = mkdtempSync(join(process.cwd(), '.issue-filter-check-'));
process.env.TASKFLOW_DB_PATH = join(dir, 'check.db');
try {
  await runMigrations();
  const tenant = await createTenant('filter-check');
  const labelA = await labels.insertLabel({ orgId: tenant.org.id, name: 'bug', color: '#123456', description: null });
  const labelB = await labels.insertLabel({ orgId: tenant.org.id, name: 'regression', color: '#123456', description: null });
  const both = [labelA.id, labelB.id];
  const definitions = [
    ['backlog', tenant.userIds.member, both, '2026-04-10T12:00:00.000Z'],
    ['todo', tenant.userIds.owner, [labelA.id], '2026-04-09T12:00:00.000Z'],
    ['in_progress', null, both, '2026-04-10T23:59:59.999Z'],
    ['in_review', tenant.userIds.member, [labelB.id], '2026-04-11T00:00:00.000Z'],
    ['done', null, both, '2026-04-10T12:00:00.000Z'],
    ['canceled', tenant.userIds.member, [], null],
  ];
  const rows = [];
  for (const [status, assigneeId, labelIds, dueAt] of definitions) {
    const input = { ...issueInput(tenant.org.id, tenant.project.id), status, assigneeId, labelIds, dueAt };
    rows.push(await repo.insertIssue(input, status === 'todo' ? tenant.userIds.member : tenant.userIds.owner, rows.length + 1));
  }
  await repo.archiveIssue(tenant.org.id, rows[4].id);
  await repo.archiveIssue(tenant.org.id, rows[5].id);
  const ids = (items) => items.map((row) => row.id).sort();
  async function check(filter, indices, actor = tenant.actors.owner) {
    const input = issueFilterSchema.parse({ orgId: tenant.org.id, ...filter, limit: 100 });
    const result = await listIssues(actor, input);
    assert.deepEqual(ids(result.items), indices.map((i) => rows[i].id).sort());
    assert.equal(result.total, indices.length);
    const decoded = parseIssueFilterParams(new URLSearchParams(issueFilterToParams(filter)));
    const urlResult = await listIssues(actor, issueFilterSchema.parse({ orgId: tenant.org.id, ...decoded, limit: 100 }));
    assert.deepEqual(ids(urlResult.items), ids(result.items));
    assert.equal(urlResult.total, result.total);
  }
  await check({ assigneeId: 'me' }, [0, 3], tenant.actors.member);
  await check({ authorId: 'me' }, [1], tenant.actors.member);
  await check({ assigneeId: null }, [2]);
  await check({ status: ['open'] }, [0, 1, 2, 3]);
  await check({ status: ['closed'], includeArchived: true }, [4, 5]);
  await check({ status: ['open', 'done', 'todo'], includeArchived: true }, [0, 1, 2, 3, 4]);
  await check({ labelIds: both }, [0, 2]);
  await check({ labelIds: [labelA.id, labelA.id, labelB.id] }, [0, 2]);
  await check({ dueBefore: '2026-04-10' }, [0, 1, 2]);
  await check({ dueBefore: '2026-04-10T12:00:00.000Z' }, [1]);
  await check({ dueBefore: '2026-04-10T14:00:00+02:00' }, [1]);
  await check({ includeArchived: 'only' }, [4, 5]);
  await check({ includeArchived: true }, [0, 1, 2, 3, 4, 5]);
  await check({ includeArchived: 'only', status: ['closed'], labelIds: both, dueBefore: '2026-04-10' }, [4]);
  const direct = await repo.listIssues(issueFilterSchema.parse({ orgId: tenant.org.id, status: ['open'] }));
  assert.equal(direct.total, 4);
  const first = await listIssues(tenant.actors.owner, { orgId: tenant.org.id, labelIds: both, limit: 1 });
  const second = await listIssues(tenant.actors.owner, { orgId: tenant.org.id, labelIds: both, limit: 1, cursor: first.nextCursor });
  assert.equal(first.total, 2);
  assert.equal(second.total, 2);
  assert.equal(second.items.length, 1);
  assert(exportIssuesSchema.safeParse({ orgId: tenant.org.id, status: ['open'], assigneeId: 'me', dueBefore: '2026-04-10', includeArchived: 'only' }).success);
  assert("'!issueFilterSchema.safeParse({ orgId: tenant.org.id, status: ['"'unknown'] }).success);
  assert("'!issueFilterSchema.safeParse({ orgId: tenant.org.id, dueBefore: '"'2026-02-30' }).success);
  assert.deepEqual(toggleStatus({ status: ['open'] }, 'closed').status, ['backlog', 'todo', 'in_progress', 'in_review', 'done', 'canceled']);
  assert.deepEqual(toggleStatus({ status: ['open', 'done'] }, 'open').status, ['done']);
  console.log('Filter vocabulary, URL/service parity, UTC date boundaries, groups, archive modes, and paginated totals passed.');
} finally {
  rmSync(dir, { recursive: true, force: true });
}
JS"

